constexpr double kInf = 1.0e99;

inline void shiftfunc(const Vec& x, Vec& xshift, const double* Os, int nx) {
    xshift.resize(nx);
    for (int i = 0; i < nx; ++i) xshift[i] = x[i] - Os[i];
}

inline void rotatefunc(const Vec& x, Vec& xrot, const double* Mr, int nx) {
    xrot.assign(nx, 0.0);
    for (int i = 0; i < nx; ++i) {
        double acc = 0.0;
        for (int j = 0; j < nx; ++j) acc += x[j] * Mr[i * nx + j];
        xrot[i] = acc;
    }
}

inline void sr_func(const Vec& x, Vec& sr_x, int nx, const double* Os, const double* Mr,
                    double sh_rate) {
    Vec y;
    shiftfunc(x, y, Os, nx);
    for (int i = 0; i < nx; ++i) y[i] *= sh_rate;
    rotatefunc(y, sr_x, Mr, nx);
}

inline double hgbat_raw(const Vec& zIn) {
    const int n = static_cast<int>(zIn.size());
    double r2 = 0.0, sumz = 0.0;
    Vec z(n);
    for (int i = 0; i < n; ++i) {
        z[i] = zIn[i] - 1.0;
        r2 += z[i] * z[i];
        sumz += z[i];
    }
    const double alpha = 0.25;
    return std::pow(std::fabs(r2 * r2 - sumz * sumz), 2.0 * alpha) + (0.5 * r2 + sumz) / double(n) + 0.5;
}

inline double rastrigin_raw(const Vec& z) {
    constexpr double kPi = 3.1415926535897932384626433832795029;
    double f = 0.0;
    for (double zi : z) f += zi * zi - 10.0 * std::cos(2.0 * kPi * zi) + 10.0;
    return f;
}

inline double schwefel_raw(const Vec& zIn) {
    const int n = static_cast<int>(zIn.size());
    double f = 0.0;
    for (int i = 0; i < n; ++i) {
        double zi = zIn[i] + 4.209687462275036e+002;
        if (zi > 500.0) {
            const double r = 500.0 - std::fmod(zi, 500.0);
            f -= r * std::sin(std::sqrt(r));
            const double tmp = (zi - 500.0) / 100.0;
            f += tmp * tmp / double(n);
        } else if (zi < -500.0) {
            const double r = 500.0 - std::fmod(std::fabs(zi), 500.0);
            f -= (-500.0 + std::fmod(std::fabs(zi), 500.0)) * std::sin(std::sqrt(r));
            const double tmp = (zi + 500.0) / 100.0;
            f += tmp * tmp / double(n);
        } else {
            f -= zi * std::sin(std::sqrt(std::fabs(zi)));
        }
    }
    f += 4.189828872724338e+002 * double(n);
    return f;
}

inline double bent_cigar_raw(const Vec& z) {
    const int n = static_cast<int>(z.size());
    double f = z[0] * z[0];
    for (int i = 1; i < n; ++i) f += 1.0e6 * z[i] * z[i];
    return f;
}

inline double ellips_raw(const Vec& z) {
    const int n = static_cast<int>(z.size());
    if (n == 1) return z[0] * z[0];
    double f = 0.0;
    for (int i = 0; i < n; ++i) f += std::pow(10.0, 6.0 * i / double(n - 1)) * z[i] * z[i];
    return f;
}

inline double escaffer6_raw(const Vec& v) {
    const int n = static_cast<int>(v.size());
    double f = 0.0;
    for (int i = 0; i < n - 1; ++i) {
        const double a = v[i], b = v[i + 1];
        const double s = std::sin(std::sqrt(a * a + b * b));
        const double t1 = s * s;
        const double t2 = 1.0 + 0.001 * (a * a + b * b);
        f += 0.5 + (t1 - 0.5) / (t2 * t2);
    }
    const double a = v[n - 1], b = v[0];
    const double s = std::sin(std::sqrt(a * a + b * b));
    const double t1 = s * s;
    const double t2 = 1.0 + 0.001 * (a * a + b * b);
    f += 0.5 + (t1 - 0.5) / (t2 * t2);
    return f;
}

inline double cf_cal(const Vec& x, int nx, const double* Os, const double* delta,
                     const double* bias, double* fit, int cf_num) {
    std::vector<double> w(cf_num, 0.0);
    double w_max = 0.0, w_sum = 0.0;
    for (int i = 0; i < cf_num; ++i) {
        fit[i] += bias[i];
        double dist2 = 0.0;
        for (int j = 0; j < nx; ++j) {
            const double d = x[j] - Os[i * nx + j];
            dist2 += d * d;
        }
        if (dist2 != 0.0) {
            w[i] = std::pow(1.0 / dist2, 0.5) * std::exp(-dist2 / (2.0 * nx * delta[i] * delta[i]));
        } else {
            w[i] = kInf;
        }
        if (w[i] > w_max) w_max = w[i];
        w_sum += w[i];
    }
    if (w_max == 0.0) {
        std::fill(w.begin(), w.end(), 1.0);
        w_sum = double(cf_num);
    }
    double f = 0.0;
    for (int i = 0; i < cf_num; ++i) f += (w[i] / w_sum) * fit[i];
    return f;
}

